/* Known-plaintext attack on the FEAL-like cipher in feal.c.
 *
 * Notation (per pair), a = R0^L0, b = L0, ctR/ctL = cipher halves, e = ctL^ctR (=R3 after pre/post mixing):
 *   S1 = (a, b^F(a^k0));  peel from ciphertext: R2 = ctR^F(e^k3), R1 = b^F(a^k0)
 *   => core equation per pair: F(a^k0) ^ F(e^k3) = b ^ ctR        (in k0, k3 only)
 *   => k1 = R1 ^ F^-1(a^d),  k2 = d ^ F^-1(R1^e),  where d = ctR^F(e^k3), R1 = b^F(a^k0)
 * Two pairs' core equations intersect in ~2^8 (k0,k3) candidates; the rest are filtered
 * by full decryption of the remaining 30 pairs.
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define N (1u << 20)

extern uint32_t F32(uint32_t);
extern uint32_t Finv32(uint32_t);

static uint32_t expand(uint32_t seed) { return (uint32_t)(seed ^ (seed << 16) ^ (seed * 12345u)); }

static uint32_t key[4];
static uint64_t merge(uint32_t l, uint32_t r) { return ((uint64_t)l << 32) | r; }

/* Copy of decrypt() from decrypt.c, using F32 (verified identical to f_function) */
static uint64_t decrypt(uint64_t ct) {
    uint32_t left = (uint32_t)ct, right = (uint32_t)(ct >> 32);
    left ^= right;
    for (int r = 3; r >= 0; r--) {
        uint32_t temp = left;
        left = right;
        uint32_t mixed = F32(temp ^ key[r]);
        right = temp;
        left ^= mixed;
    }
    right ^= left;
    return merge(left, right);
}

static int cmp64(const void *p, const void *q) {
    uint64_t a = *(const uint64_t *)p, b = *(const uint64_t *)q;
    return a < b ? -1 : (a > b);
}

/* lower_bound of top-32-bits equal to val */
static int lb(const uint64_t *t, uint64_t val) {
    int lo = 0, hi = N;
    while (lo < hi) {
        int mid = (lo + hi) >> 1;
        if (t[mid] >> 32 < val) lo = mid + 1; else hi = mid;
    }
    return lo;
}

int main(void) {
    static uint64_t pt[64], ct[64];
    FILE *fp = fopen("/app/pairs.txt", "r");
    if (!fp) { perror("/app/pairs.txt"); return 1; }
    int n = 0;
    while (n < 64 && fscanf(fp, "%lu %lu", (unsigned long *)&pt[n], (unsigned long *)&ct[n]) == 2) n++;
    fclose(fp);
    printf("loaded %d pairs\n", n);
    if (n < 3) { fprintf(stderr, "need at least 3 pairs\n"); return 1; }

    uint32_t a[64], b[64], ctR[64], e[64], rhs[64];
    for (int i = 0; i < n; i++) {
        uint32_t L = (uint32_t)(pt[i] >> 32), R = (uint32_t)pt[i];
        a[i]   = R ^ L;                    /* right after pre-round mixing */
        b[i]   = L;
        ctR[i] = (uint32_t)(ct[i] >> 32);
        e[i]   = ctR[i] ^ (uint32_t)ct[i]; /* = R3, known without keys     */
        rhs[i] = b[i] ^ ctR[i];
    }

