#include <stdint.h>

static inline uint8_t rot2(uint8_t t)  { return (uint8_t)(((t << 2) | (t >> 6)) & 0xFF); }
static inline uint8_t rot2i(uint8_t t) { return (uint8_t)(((t >> 2) | (t << 6)) & 0xFF); }

/* Matches f_function() in feal.c: x[0] is the low byte, out = y0 | y1<<8 | y2<<16 | y3<<24 */
uint32_t F32(uint32_t v) {
    uint8_t x0 = (uint8_t)v, x1 = (uint8_t)(v >> 8), x2 = (uint8_t)(v >> 16), x3 = (uint8_t)(v >> 24);
    uint8_t y2 = rot2((x3 ^ x2) + (x1 ^ x0) + 1);
    uint8_t y3 = rot2(x3 + y2);
    uint8_t y1 = rot2((x1 ^ x0) + y2);
    uint8_t y0 = rot2(x0 + y1 + 1);
    return (uint32_t)y0 | ((uint32_t)y1 << 8) | ((uint32_t)y2 << 16) | ((uint32_t)y3 << 24);
