/* Known-plaintext attack on the FEAL-like cipher in feal.c.
 *
 * Per pair, with a = R0^L0, b = L0, ctR/ctL = cipher halves, e = ctL^ctR (=S4.L = R3):
 *   d_i  = ctR_i ^ F(e_i^k3)          (depends only on k3)
 *   R1_i = b_i   ^ F(a_i^k0)          (depends only on k0)
 *   k1   = R1_i ^ F^-1(a_i ^ d_i)     (must hold for every pair i)
 *   k2   = d_i  ^ F^-1(R1_i ^ e_i)
 * Equality of k1 for pairs 0 and 1 gives a 32-bit equation that separates:
 *   L(k0) := (b0^b1) ^ F(a0^k0) ^ F(a1^k0)
 *   M(k3) := F^-1(a0^ctR0^F(e0^k3)) ^ F^-1(a1^ctR1^F(e1^k3))
 *   L(k0) == M(k3)        ->  ~2^8 (k0,k3) candidates, then peel k1,k2 and verify.
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define N (1u << 20)

extern uint32_t F32(uint32_t);
extern uint32_t Finv32(uint32_t);

static uint32_t expand(uint32_t seed) { return (uint32_t)(seed ^ (seed << 16) ^ (seed * 12345u)); }

static uint32_t key[4];
static uint64_t merge(uint32_t l, uint32_t r) { return ((uint64_t)l << 32) | r; }

/* Copy of decrypt() from decrypt.c, using F32 (verified identical to f_function) */
static uint64_t decrypt(uint64_t ct) {
    uint32_t left = (uint32_t)ct, right = (uint32_t)(ct >> 32);
    left ^= right;
    for (int r = 3; r >= 0; r--) {
        uint32_t temp = left;
        left = right;
        uint32_t mixed = F32(temp ^ key[r]);
        right = temp;
        left ^= mixed;
    }
    right ^= left;
    return merge(left, right);
}

static int cmp64(const void *p, const void *q) {
    uint64_t a = *(const uint64_t *)p, b = *(const uint64_t *)q;
    return a < b ? -1 : (a > b);
}

/* lower_bound of top-32-bits equal to val */
static int lb(const uint64_t *t, uint64_t val) {
    int lo = 0, hi = N;
    while (lo < hi) {
        int mid = (lo + hi) >> 1;
        if (t[mid] >> 32 < val) lo = mid + 1; else hi = mid;
    }
    return lo;
}

int main(void) {
    static uint64_t pt[64], ct[64];
    FILE *fp = fopen("/app/pairs.txt", "r");
    if (!fp) { perror("/app/pairs.txt"); return 1; }
    int n = 0;
    while (n < 64 && fscanf(fp, "%lu %lu", (unsigned long *)&pt[n], (unsigned long *)&ct[n]) == 2) n++;
    fclose(fp);
    printf("loaded %d pairs\n", n);
    if (n < 3) { fprintf(stderr, "need at least 3 pairs\n"); return 1; }

    uint32_t a[64], b[64], ctR[64], e[64];
    for (int i = 0; i < n; i++) {
        uint32_t L = (uint32_t)(pt[i] >> 32), R = (uint32_t)pt[i];
        a[i]   = R ^ L;
        b[i]   = L;
        ctR[i] = (uint32_t)(ct[i] >> 32);
        e[i]   = ctR[i] ^ (uint32_t)ct[i];
    }

    static uint64_t LT[N], MT[N];
    uint32_t bb = b[0] ^ b[1];
    for (uint32_t s = 0; s < N; s++) {
        uint32_t k0 = expand(s);
        LT[s] = ((uint64_t)(bb ^ F32(a[0] ^ k0) ^ F32(a[1] ^ k0)) << 32) | s;
    }
    for (uint32_t s = 0; s < N; s++) {
        uint32_t k3 = expand(s);
        uint32_t m = Finv32(a[0] ^ ctR[0] ^ F32(e[0] ^ k3))
                   ^ Finv32(a[1] ^ ctR[1] ^ F32(e[1] ^ k3));
        MT[s] = ((uint64_t)m << 32) | s;
    }
    qsort(LT, N, sizeof *LT, cmp64);
    qsort(MT, N, sizeof *MT, cmp64);
    printf("searching (k0,k3) via L(k0)==M(k3)...\n");

    long cand = 0;
    for (int i = 0; i < N; i++) {
        uint64_t val = LT[i] >> 32;
        int lo = lb(MT, val);
        if (lo >= N || (MT[lo] >> 32) != val) continue;
        for (int q = lo; q < N && (MT[q] >> 32) == val; q++) {
            uint32_t k0 = (uint32_t)LT[i], k3 = (uint32_t)MT[q];
            cand++;
            uint32_t d  = ctR[0] ^ F32(e[0] ^ k3);
            uint32_t R1 = b[0]  ^ F32(a[0] ^ k0);
            uint32_t k1 = R1 ^ Finv32(a[0] ^ d);
            uint32_t k2 = d  ^ Finv32(R1 ^ e[0]);
            printf("candidate %ld: k0=%08x k1=%08x k2=%08x k3=%08x\n",
                   cand, k0, k1, k2, k3);
            key[0] = k0; key[1] = k1; key[2] = k2; key[3] = k3;
            int ok = 1;
            for (int i2 = 0; i2 < n; i2++)
                if (decrypt(ct[i2]) != pt[i2]) { ok = 0; break; }
            if (!ok) continue;

            static uint64_t Etab[N];
            for (uint32_t s = 0; s < N; s++) Etab[s] = ((uint64_t)expand(s) << 32) | s;
            qsort(Etab, N, sizeof *Etab, cmp64);
            uint32_t seeds[4];
            for (int i2 = 0; i2 < 4; i2++) {
                int li = lb(Etab, key[i2]);
                if (li >= N || (Etab[li] >> 32) != (uint64_t)key[i2]) {
                    fprintf(stderr, "no seed for key %d\n", i2); return 1;
                }
                seeds[i2] = (uint32_t)Etab[li];
            }
            printf("KEY FOUND  seeds: %05x %05x %05x %05x\n", seeds[0], seeds[1], seeds[2], seeds[3]);
            printf("round keys: %08x %08x %08x %08x\n", key[0], key[1], key[2], key[3]);

            FILE *fin = fopen("/app/ciphertexts.txt", "r");
            FILE *fout = fopen("/app/plaintexts.txt", "w");
            if (!fin || !fout) { perror("ciphertexts.txt"); return 1; }
            unsigned long c;
            int m = 0;
            while (fscanf(fin, "%lu", &c) == 1) {
                fprintf(fout, "%lu\n", (unsigned long)decrypt((uint64_t)c));
                m++;
            }
            fclose(fin); fclose(fout);
            printf("decrypted %d ciphertexts -> /app/plaintexts.txt\n", m);
            return 0;
        }
    }
    fprintf(stderr, "no key found (unexpected), candidates tested: %ld\n", cand);
    return 1;
}
